effect.shader:

    vec4 newLayer( vec4 a, vec4 b) {
    return a * (1. - b.a) + b;
    }

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord.xy

   /////////////////////////

        float random2 (in vec2 st) {
            return fract(sin(dot(st.xy,vec2(12.9898,78.233)))* 43758.5453123);
        }

        // vec2 myPatternx(in vec2 uvx){
            // vec2 uv2x = uvx;
            // uv2x.x = uv2x.x + 0.1 * (random2(uvx));
            // return uv2x - uvx;
        // }

        // vec2 myPatterny(in vec2 uvy){
            // vec2 uv2y = uvy;
            // uv2y.y = uv2y.y + 0.1 * (random2(uvy));
            // return uv2y - uvy;
        // }

        vec2 myPattern(in vec2 uv){
        	vec2 uv2 = uv;
            if(type == 0) { uv2.x = uv2.x + 0.1 * (random2(uv)); }
            else if(type == 1) { uv2.y = uv2.y + 0.1 * (random2(uv)); }
            else if(type == 2) { 
            uv2.x = uv2.x + 0.1 * (random2(uv)); 
            uv2.y = uv2.y + 0.1 * (random2(uv));
            }
            return uv2 - uv;
        }

   /////////////////////////
    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        // vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

        // vec2 xxx;
        // xxx = acScreenNorm; 
        // xxx += vec2((-25.0), (0.0))*vec2(-1.,1.)/500.;

        // vec2 yyy;
        // yyy = acScreenNorm; 
        // yyy += vec2((0.0), (25.0))*vec2(-1.,1.)/500.;

        vec2 TanRyu;
        TanRyu = acScreenNorm; 

            if(type == 0) { TanRyu += vec2((-25.0), (0.0))*vec2(-1.,1.)/500.; }
            else if(type == 1) { TanRyu += vec2((0.0), (25.0))*vec2(-1.,1.)/500.; }
            else if(type == 2) { TanRyu += vec2((-25.0), (25.0))*vec2(-1.,1.)/500.; }

        /////////////////////////

    	vec4 fragColor;

          vec2 uv = TanRyu;
          vec2 p = uv;
          for (int i = 0; i < 10; i ++) p -= myPattern(p) * 0.1;
          vec3 col = texture2DCv(inputImg.texture, p).rgb;

          fragColor = vec4(col, 1.0);

    	gl_FragColor = mix(texColor, fragColor, alpha) * texColor.a;
    	// }
    }
